class Solution {
  public TreeNode insertIntoBST(TreeNode root, int e) {
    if (root == null) return new TreeNode(e);
    TreeNode current = root;
    while (true) {
      if (e < current.val) {
        if (current.left == null) {
          current.left = new TreeNode(e);
          break;
        }
        current = current.left;
      } else if (e > current.val) {
        if (current.right == null) {
          current.right = new TreeNode(e);
          break;
        }
        current = current.right;
      } else {
        return root;
      }
    }
    return root;
  }
}

